func (v PolicyValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 7)

	var val tftypes.Value
	var err error

	attrTypes["author_can_approve"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["committers_can_approve"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["defined_at"] = basetypes.ObjectType{
		AttrTypes: DefinedAtValue{}.AttributeTypes(ctx),
	}.TerraformType(ctx)
	attrTypes["enforcement"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["last_pusher_can_approve"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["reset_on_push"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["updated_at"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 7)

		val, err = v.AuthorCanApprove.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["author_can_approve"] = val

		val, err = v.CommittersCanApprove.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["committers_can_approve"] = val

		val, err = v.DefinedAt.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["defined_at"] = val

		val, err = v.Enforcement.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["enforcement"] = val

		val, err = v.LastPusherCanApprove.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["last_pusher_can_approve"] = val

		val, err = v.ResetOnPush.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["reset_on_push"] = val

		val, err = v.UpdatedAt.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["updated_at"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

